<script lang="ts">
 import {page} from '$app/stores';import Icon from '$lib/components/Icon.svelte';import FolderTree from './FolderTree.svelte';import {fileState,getTree,rootFor,mutateTree,readUploads,snapshotSource} from '$lib/files/store';import {workspace} from '$lib/stores/workspace';import {basename,dirname,children,createEntry,addUploads,renameEntry,deleteEntry,editEntry,encodeText,decodeText,decodeBytes,byteCount,sizeLabel,treeBytes,type Tree} from '$lib/files/model.js';
 export let fixedKey='';export let picker=false;export let onSelect:(source:ReturnType<typeof snapshotSource>)=>void=()=>{};export let initialKey='';export let initialPath='';
 let selection=initialKey||fixedKey,path=initialPath,initialized=false,action:'folder'|'file'|'rename'|'edit'|'preview'|''='',entry='',name='',content='',error='',notice='',busy=false;let uploadInput:HTMLInputElement,folderInput:HTMLInputElement;
 $: spaces=$fileState.spaces;$: projects=$workspace.projects;$: options=[...spaces.map(s=>({key:'space:'+s.id,name:s.name,root:'files'})),...projects.map(p=>({key:'project:'+p.id,name:p.name,root:rootFor(p.framework)}))];
 $: target=options.find(t=>t.key===(fixedKey||selection))||(!fixedKey?options[0]:undefined);
 $: data=target?getTree($fileState,target.key,projects.find(p=>target?.key==='project:'+p.id)?.framework):undefined;
 $: tree=data||{} as Tree;
 $: active=target&&tree[path]?.kind==='folder'&&(path===target.root||path.startsWith(target.root+'/'))?path:target?.root||'';
 $: entries=children(tree,active);
 $: space=spaces.find(s=>target?.key==='space:'+s.id);
 $: if(target&&!initialized){initialized=true;selection=target.key;if(initialPath&&tree[initialPath]?.kind==='file')path=dirname(initialPath);}
 function switchTarget(key:string,root:string){selection=key;path=root;action='';error='';notice='';}
 function openFolder(p:string){path=p;action='';error='';}
 function run(fn:()=>void){try{error='';fn();}catch(e){error=e instanceof Error?e.message:'File operation failed.';}}
 function start(mode:typeof action,p=''){action=mode;entry=p;name=mode==='rename'?basename(p):'';content='';error='';notice='';if(mode==='edit'){try{const f=tree[p];if(f.kind==='file')content=decodeText(f.data);}catch{action='preview';}}}
 function fileOpen(p:string){if(tree[p]?.kind==='folder'){openFolder(p);return;}if(picker){if(/\.zip$/i.test(p))choose(p);return;}start(/\.(txt|md|json|css|js|ts|html?|xml|php|csv|yml|yaml|py|sql|sh|ini|toml|conf)$/i.test(p)?'edit':'preview',p);}
 function save(){run(()=>{if(!target)return;const key=target.key;if(action==='folder'||action==='file')mutateTree(key,t=>createEntry(t,active,name.trim(),action==='folder'?'folder':'file'));else if(action==='rename')mutateTree(key,t=>renameEntry(t,entry,name.trim()));else if(action==='edit')mutateTree(key,t=>editEntry(t,entry,encodeText(content)));else return;action='';notice='Sample changes saved.';});}
 async function upload(list:FileList|null){if(!target||!list?.length)return;const key=target.key,destination=active,selected=Array.from(list);busy=true;error='';try{const files=await readUploads(selected);mutateTree(key,t=>addUploads(t,destination,files));notice='Sample files saved locally. No server upload.';}catch(e){error=e instanceof Error?e.message:'Upload failed.';}finally{busy=false;uploadInput.value='';folderInput.value='';}}
 function remove(p:string){if(!target||!window.confirm('Delete '+basename(p)+' and any contents from this sample workspace?'))return;run(()=>{if(target)mutateTree(target.key,t=>deleteEntry(t,p));action='';notice='Sample item deleted.';});}
 function download(p:string){run(()=>{const f=tree[p];if(!f||f.kind!=='file')return;const blob=new Blob([decodeBytes(f.data)]);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=basename(p);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
 async function copyUrl(p:string){if(!space||space.access!=='Public read')return;try{await navigator.clipboard.writeText('https://storage.drevanta.example/'+encodeURIComponent(space.id)+'/'+p.split('/').slice(1).map(encodeURIComponent).join('/'));notice='Illustrative URL copied. It does not serve files.';}catch{error='Clipboard unavailable.';}}
 function choose(p:string){run(()=>{if(!target)return;onSelect(snapshotSource(target.key,p));notice='Source selected. The original files remain unchanged.';});}
 const direct=(key:string,p:string)=>'/projects/new?source='+encodeURIComponent(key)+'&path='+encodeURIComponent(p);
</script>
{#if target}<div class="x-workspace native-file-workspace"><section class="card x-tree"><div class="row between wrap"><h3>{picker?'Choose source':'Files'}</h3>{#if !picker&&!fixedKey}<a class="btn ghost small" href="/storage">Storage</a>{/if}</div>{#each [{title:'STORAGE SPACES',prefix:'space:'},{title:'PROJECT FILES',prefix:'project:'}] as group}{#if !fixedKey||fixedKey.startsWith(group.prefix)}{#if !fixedKey}<div class="eyebrow x-group-label">{group.title}</div>{/if}{#each options.filter(t=>t.key.startsWith(group.prefix)&&(!fixedKey||t.key===fixedKey)) as t (t.key)}<button class="x-root" class:selected={target.key===t.key} on:click={()=>switchTarget(t.key,t.root)}><Icon name={group.prefix==='space:'?'Storage':'Projects'}/><span class="grow">{t.name}</span><span>{target.key===t.key?'▾':'▸'}</span></button>{#if target.key===t.key&&tree[t.root]}<FolderTree {tree} folder={t.root} current={active} onOpen={openFolder}/>{/if}{:else}<small class="x-group-label">None yet</small>{/each}{/if}{/each}<div class="x-tree-note muted tiny">Only workspace source files are shown. System directories and credentials are not accessible.</div></section><div class="x-content"><section class="card x-browser"><div class="row between wrap x-browser-head"><div class="grow"><h3>{target.name}</h3><p class="subtitle">{space?'Independent storage · '+space.access:'Project files'}</p></div>{#if space&&!picker}<a class="btn secondary small" href={'/storage/'+space.id}>Storage settings</a>{/if}</div><div class="x-location row wrap"><Icon name="Projects"/><span class="strong">{target.name}</span>{#each active.split('/') as part,i}<span class="muted">/</span><button class="link-btn" on:click={()=>openFolder(active.split('/').slice(0,i+1).join('/'))}>{part}</button>{/each}</div><div class="x-actions row wrap">{#if active!==target.root}<button class="btn secondary small" on:click={()=>openFolder(dirname(active))}>Up</button>{/if}{#if picker}<button class="btn primary" on:click={()=>choose(active)}>Use this folder</button>{:else}<button class="btn primary" disabled={busy} on:click={()=>uploadInput.click()}><Icon name="Upload"/>{busy?'Reading…':'Upload'}</button><button class="btn secondary" disabled={busy} on:click={()=>folderInput.click()}>Upload folder</button><button class="btn secondary" disabled={busy} on:click={()=>start('folder')}><Icon name="Plus"/>New folder</button><button class="btn secondary" disabled={busy} on:click={()=>start('file')}><Icon name="File"/>New file</button><input hidden type="file" multiple bind:this={uploadInput} on:change={()=>upload(uploadInput.files)}/><input hidden type="file" multiple {...{webkitdirectory:''}} bind:this={folderInput} on:change={()=>upload(folderInput.files)}/>{/if}</div>
{#if error}<p class="error native-file-note" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle native-file-note" role="status">{notice}</p>{/if}
{#if !picker&&action}<div class="native-file-note well stack"><div class="row between wrap"><strong>{action==='folder'?'New folder':action==='file'?'New file':action==='rename'?'Rename':action==='edit'?'Edit file':'File preview'} {entry?basename(entry):''}</strong><button class="btn secondary small" on:click={()=>action=''}>Close</button></div>{#if action==='preview'}<p class="subtitle">Binary preview unavailable. Download the file to inspect it locally.</p><button class="btn secondary" on:click={()=>download(entry)}>Download</button>{:else}<form class="stack" on:submit|preventDefault={save}>{#if action==='edit'}<label class="field">File contents<textarea rows="12" class="mono" bind:value={content}></textarea></label>{:else}<label class="field">Name<input required bind:value={name}/></label>{/if}<div><button class="btn primary" type="submit">Save</button></div></form>{/if}</div>{/if}
<div class="table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Size</th><th>Actions</th></tr></thead><tbody>{#each entries.filter(p=>!picker||tree[p].kind==='folder'||/\.zip$/i.test(p)) as p (p)}<tr><td><div class="row"><Icon name={tree[p].kind==='folder'?'Projects':'File'}/><button class="link-btn native-path" on:click={()=>fileOpen(p)}>{basename(p)}</button></div></td><td>{tree[p].kind==='folder'?'Folder':'File'}</td><td>{tree[p].kind==='file'?sizeLabel(byteCount((tree[p] as {kind:'file';data:string}).data)):'—'}</td><td><div class="table-actions">{#if picker}{#if tree[p].kind==='file'}<button class="btn primary small" on:click={()=>choose(p)}>Select ZIP</button>{:else}<button class="btn secondary small" on:click={()=>choose(p)}>Use folder</button>{/if}{:else}{#if tree[p].kind==='folder'||/\.zip$/i.test(p)}<a class="btn secondary small" href={direct(target.key,p)}>Deploy</a>{/if}{#if tree[p].kind==='file'}<button class="btn secondary small" on:click={()=>download(p)}>Download</button>{#if space?.access==='Public read'}<button class="btn secondary small" on:click={()=>copyUrl(p)}>Copy URL</button>{/if}{/if}<button class="btn secondary small" on:click={()=>start('rename',p)}>Rename</button><button class="btn danger small" on:click={()=>remove(p)}>Delete</button>{/if}</div></td></tr>{:else}<tr><td colspan="4">{picker?'No ZIP archives or folders at this location.':'This folder is empty.'}</td></tr>{/each}</tbody></table></div><div class="x-browser-foot muted tiny">{entries.length} items · {sizeLabel(treeBytes(tree))} in this workspace · Browser demo</div></section></div></div>{:else}<section class="card"><h3>No files yet</h3><p class="subtitle">Create a storage space or project first.</p>{#if !picker}<a class="btn primary" href="/storage">Storage</a>{/if}</section>{/if}
